pragma solidity ^0.8.28;

/**
 * Verbatim interface of the official ENS Verifiable Factory
 * (github.com/ensdomains/verifiable-factory, src/IVerifiableFactory.sol,
 * fetched 2026-11-05). ref: R-ENS-4, docs.ens.domains/ensv2/verifiable-factory.
 */
interface IVerifiableFactory {
    error VerificationFailed(address proxy);

    event ProxyDeployed(address indexed sender, address indexed proxyAddress, uint256 salt, address implementation);

    function deployProxy(address implementation, uint256 salt, bytes memory data) external returns (address);

    function predictProxyAddress(address deployer, uint256 salt) external view returns (address proxy);

    function verifyContract(address proxy) external view returns (address implementation);
}

src/factory/UUPSProxyLogic.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IProxyAuthorization} from "./IProxyAuthorization.sol";
import {IUUPSProxy} from "./IUUPSProxy.sol";

/**
 * Verbatim of the official ENS UUPS proxy logic
 * (github.com/ensdomains/verifiable-factory, src/UUPSProxyLogic.sol,
 * fetched 2026-11-05; Solidity pragma bumped ^0.8.20 → ^0.8.28 for the
 * Dabbawala harness toolchain — no behavioral change).
 * ref: R-ENS-4, docs.ens.domains/ensv2/verifiable-factory.
 */
contract UUPSProxyLogic is IUUPSProxy {
    /// @dev `keccak256(bytes("eip1967.proxy.implementation")) - 1`.
    bytes32 internal constant _IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    /// @dev `bytes4(keccak256(bytes("ImplementationCannotBeZeroAddress()")))`.
    uint256 internal constant _IMPLEMENTATION_CANNOT_BE_ZERO_ADDRESS_ERROR_SELECTOR = 0x0760838f;

    /// @dev `bytes4(keccak256(bytes("AlreadyInitialized()")))`.
    uint256 internal constant _ALREADY_INITIALIZED_ERROR_SELECTOR = 0x0dc149f0;

    /// @dev `bytes4(keccak256(bytes("UpgradeNotAllowedInContext()")))`.
    uint256 internal constant _UPGRADE_NOT_ALLOWED_IN_CONTEXT_ERROR_SELECTOR = 0x784cf700;

    /// @dev `bytes4(keccak256(bytes("UnexpectedUpgrade()")))`.
    uint256 internal constant _UNEXPECTED_UPGRADE_ERROR_SELECTOR = 0x2be61883;

    /// @dev `bytes4(keccak256(bytes("ERC1967InvalidImplementation(address)")))`.
    uint256 internal constant _ERC1967_INVALID_IMPLEMENTATION_ERROR_SELECTOR = 0x4c9c8ce3;

    /// @dev `bytes4(keccak256(bytes("ERC1967NonPayable()")))`.
    uint256 internal constant _ERC1967_NON_PAYABLE_ERROR_SELECTOR = 0xb398979f;

    /// @dev `bytes4(keccak256(bytes("Upgraded(address)")))`.
    uint256 internal constant _UPGRADED_EVENT_SELECTOR =
        0xbc7cd75a20ee27fd9adebab32041f755214dbc6bffa90cc0225b39da2e5c2d3b;

    address public immutable verifiableProxyFactory;

    constructor() {
        verifiableProxyFactory = msg.sender;
    }

    function initialize(address implementation, bytes calldata data) external payable {
        assembly {
            if eq(implementation, 0) {
                mstore(0, _IMPLEMENTATION_CANNOT_BE_ZERO_ADDRESS_ERROR_SELECTOR)
                revert(0x1c, 0x04)
            }
            if iszero(eq(sload(_IMPLEMENTATION_SLOT), 0)) {
                mstore(0, _ALREADY_INITIALIZED_ERROR_SELECTOR)
                revert(0x1c, 0x04)
            }
            if iszero(extcodesize(implementation)) {
                mstore(0, _ERC1967_INVALID_IMPLEMENTATION_ERROR_SELECTOR)
                mstore(0x20, implementation)
                revert(0x1c, 0x24)
            }
            sstore(_IMPLEMENTATION_SLOT, implementation)
            log2(0, 0, _UPGRADED_EVENT_SELECTOR, implementation)

            let dlength := data.length
            switch dlength
            case 0 {
                if callvalue() {
                    mstore(0, _ERC1967_NON_PAYABLE_ERROR_SELECTOR)
                    revert(0x1c, 0x04)
                }
            }
            default {
                calldatacopy(0, data.offset, dlength)
                let result := delegatecall(gas(), implementation, 0, dlength, 0, 0)
                if iszero(result) {
                    returndatacopy(0, 0, returndatasize())
                    revert(0, returndatasize())
                }
            }
        }
    }

    function getVerifiableProxyData() public view returns (bytes32 salt, address implementation) {
        assembly {
            extcodecopy(address(), 0, sub(extcodesize(address()), 0x20), 0x20)
            salt := mload(0)
            implementation := sload(_IMPLEMENTATION_SLOT)
        }
    }

    function upgradeToAndCall(address newImplementation, bytes calldata) external payable {
        if (newImplementation == address(0)) revert ImplementationCannotBeZeroAddress();

        address implementation = _implementation();
        if (implementation == address(0)) revert ImplementationNotSet();

        IProxyAuthorization newImpl = IProxyAuthorization(newImplementation);
        if (!newImpl.canUpgradeFrom(implementation)) {
            revert InvalidUpgradeTarget(implementation, newImplementation);
        }

        _delegateUpgrade(implementation, newImplementation);
    }

    function _implementation() internal view returns (address impl) {
        assembly {
            impl := sload(_IMPLEMENTATION_SLOT)
        }
    }

    function _delegate(address implementation, bool checkImplementation) internal {
        assembly {
            calldatacopy(0, 0, calldatasize())

            let result := delegatecall(gas(), implementation, 0, calldatasize(), 0, 0)

            if checkImplementation {
                if iszero(eq(implementation, sload(_IMPLEMENTATION_SLOT))) {
                    mstore(0, _UPGRADE_NOT_ALLOWED_IN_CONTEXT_ERROR_SELECTOR)
                    revert(0x1c, 0x04)
                }
            }

            returndatacopy(0, 0, returndatasize())

            switch result
            case 0 {
                revert(0, returndatasize())
            }
            default {
                return(0, returndatasize())
            }
        }
    }

    function _delegateUpgrade(address implementation, address expectedImplementation) internal {
        assembly {
            calldatacopy(0, 0, calldatasize())

            let result := delegatecall(gas(), implementation, 0, calldatasize(), 0, 0)
            if iszero(result) {
                returndatacopy(0, 0, returndatasize())
                revert(0, returndatasize())
            }

            if iszero(eq(expectedImplementation, sload(_IMPLEMENTATION_SLOT))) {
                mstore(0, _UNEXPECTED_UPGRADE_ERROR_SELECTOR)
                revert(0x1c, 0x04)
            }

            returndatacopy(0, 0, returndatasize())
            return(0, returndatasize())
        }
    }

    fallback() external payable {
        _delegate(_implementation(), true);
    }
}

src/factory/VerifiableFactoryReplica.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {CloneProxyBytecode} from "./CloneProxyBytecode.sol";
import {UUPSProxyLogic} from "./UUPSProxyLogic.sol";
import {IUUPSProxy} from "./IUUPSProxy.sol";
import {IVerifiableFactory} from "./IVerifiableFactory.sol";

/**
 * @title VerifiableFactoryReplica
 * @notice Local-Hardhat replica of the official ENS Verifiable Factory
 *         (github.com/ensdomains/verifiable-factory, src/VerifiableFactory.sol,
 *         fetched 2026-11-05). Differences from the official contract: the
 *         OpenZeppelin `Create2.computeAddress` helper is inlined
 *         (keccak(0xff ++ factory ++ salt ++ keccak(creationCode))) and the
 *         bare `revert(0, 0)` on CREATE2 failure is replaced with the typed
 *         ProxyDeployFailed error. Behavior and ABI are otherwise identical
 *         to the official factory, so the Dabbawala deployment scripts run
 *         the same call sequence against the protocol-owned Sepolia factory
 *         (ref: R-ENS-5) and this replica interchangeably.
 * ref: R-ENS-4, docs.ens.domains/ensv2/verifiable-factory.
 */
contract VerifiableFactoryReplica is IVerifiableFactory {
    /// @notice CREATE2 derived an address that already holds code.
    error ProxyDeployFailed();

    address public immutable proxyLogic;

    constructor() {
        proxyLogic = address(new UUPSProxyLogic());
    }

    /**
     * @dev Deploys a new verifiable proxy clone at a deterministic address.
     *
     * The deployed proxy is an EIP-1167-style clone that delegates proxy
     * mechanics to the factory's `proxyLogic` contract. The clone runtime also
     * appends the derived salt so the factory can later verify the proxy's
     * CREATE2 address.
     *
     * The CREATE2 salt is `keccak256(abi.encode(msg.sender, salt))`, so two
     * callers can reuse the same user salt without colliding.
     */
    function deployProxy(address implementation, uint256 salt, bytes memory data) external returns (address proxy) {
        bytes32 outerSalt = keccak256(abi.encode(msg.sender, salt));
        bytes memory executableBytecode = _proxyCreationCode(outerSalt);

        assembly ("memory-safe") {
            proxy := create2(0, add(executableBytecode, 0x20), mload(executableBytecode), outerSalt)
            if iszero(proxy) {
                revert(0, 0)
            }
        }

        IUUPSProxy(proxy).initialize(implementation, data);

        emit ProxyDeployed(msg.sender, proxy, salt, implementation);
    }

    /**
     * @dev Predicts the proxy address for a deployer and user salt, whether
     *      or not it is deployed. The address is independent of the
     *      implementation and initialization data.
     */
    function predictProxyAddress(address deployer, uint256 salt) external view returns (address proxy) {
        return _computeProxyAddress(keccak256(abi.encode(deployer, salt)));
    }

    /**
     * @dev Verifies a proxy contract and returns its current implementation.
     *      Retrieves the salt appended to the proxy's runtime code and
     *      reconstructs the address to prove provenance by this factory.
     */
    function verifyContract(address proxy) public view returns (address implementation) {
        if (!_isContract(proxy)) revert VerificationFailed(proxy);

        try IUUPSProxy(proxy).getVerifiableProxyData() returns (bytes32 salt, address actualImplementation) {
            if (_computeProxyAddress(salt) == proxy) return actualImplementation;
        } catch {}
        revert VerificationFailed(proxy);
    }

    function _computeProxyAddress(bytes32 salt) private view returns (address) {
        bytes32 codeHash = keccak256(_proxyCreationCode(salt));
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), address(this), salt, codeHash)))));
    }

    function _proxyCreationCode(bytes32 salt) private view returns (bytes memory) {
        return CloneProxyBytecode.creationCode(proxyLogic, salt);
    }

    function _isContract(address account) internal view returns (bool) {
        uint256 size;
        assembly ("memory-safe") {
            size := extcodesize(account)
        }
        return size > 0;
    }
}

